/*
Write a single DELETE statement that removes all rows from the `baskets` table where the associated shopper (via `shopper_id`) has a `status` of 'inactive' in the `shoppers` table.
After the deletion, return all remaining baskets ordered by `basket_id` ascending.
*/
DELETE FROM baskets
WHERE shopper_id IN (SELECT shopper_id FROM shoppers WHERE status = 'inactive');

SELECT * FROM baskets ORDER BY basket_id;
